<?php $pageTitle='Add T-shirt';require '../includes/admin-header.php';$pdo=db();$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){try{$image='assets/images/products/tee.svg';if(!empty($_FILES['image']['tmp_name'])&&is_uploaded_file($_FILES['image']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp']))throw new Exception('Use a JPG, PNG, or WEBP image.');$name='tee_'.bin2hex(random_bytes(5)).'.'.$ext;$dir=__DIR__.'/../assets/images/products/';if(!is_dir($dir))mkdir($dir,0755,true);move_uploaded_file($_FILES['image']['tmp_name'],$dir.$name);$image='assets/images/products/'.$name;}$stock=array_sum(array_map('intval',$_POST['size_stock']??[]));$status=$stock?'active':'out_of_stock';$q=$pdo->prepare('INSERT INTO products(category_id,name,brand,description,specifications,material,fit_type,color,original_price,discount_percent,image,stock_quantity,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['brand'])?:'OVERSO',trim($_POST['description']),trim($_POST['specifications']),trim($_POST['material'])?:'240 GSM Cotton',trim($_POST['fit_type'])?:'Relaxed Oversized',trim($_POST['color']),(float)$_POST['original_price'],(float)$_POST['discount_percent'],$image,$stock,$_POST['status']??$status]);$pid=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO product_sizes(product_id,size,stock_quantity) VALUES(?,?,?)');foreach(['S','M','L','XL','XXL','XXXL'] as $size)$s->execute([$pid,$size,(int)($_POST['size_stock'][$size]??0)]);flash('success','T-shirt added.');go('admin/products.php');}catch(Throwable $e){flash('danger',$e->getMessage());}} ?><form method="post" enctype="multipart/form-data" class="card card-body"><div class="row g-3"><div class="col-md-6"><label>Product name</label><input class="form-control" name="name" required></div><div class="col-md-3"><label>Brand</label><input class="form-control" name="brand" value="OVERSO"></div><div class="col-md-3"><label>Collection</label><select class="form-select" name="category_id"><?php foreach($categories as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach ?></select></div><div class="col-12"><label>Description</label><textarea class="form-control" name="description" required></textarea></div><div class="col-md-4"><label>Material</label><input class="form-control" name="material" value="240 GSM Cotton"></div><div class="col-md-4"><label>Fit type</label><input class="form-control" name="fit_type" value="Relaxed Oversized"></div><div class="col-md-4"><label>Colour</label><input class="form-control" name="color" required></div><div class="col-md-3"><label>Original price</label><input class="form-control" type="number" name="original_price" required></div><div class="col-md-3"><label>Discount %</label><input class="form-control" type="number" name="discount_percent" value="0"></div><div class="col-md-3"><label>Status</label><select class="form-select" name="status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="out_of_stock">Out of Stock</option></select></div><div class="col-md-3"><label>Product image</label><input class="form-control" type="file" name="image" accept="image/*"></div><div class="col-12"><label>Specifications</label><input class="form-control" name="specifications" placeholder="e.g. 240 GSM, screen print"></div><div class="col-12"><b>Stock by size</b><div class="row mt-1"><?php foreach(['S','M','L','XL','XXL','XXXL'] as $s): ?><div class="col"><label><?=$s?></label><input class="form-control" type="number" min="0" name="size_stock[<?=$s?>]" value="0"></div><?php endforeach ?></div></div><div><button class="btn btn-dark">Save T-shirt</button></div></div></form><?php require '../includes/admin-footer.php'; ?>
